// ---------------------------------------------------------------------------
// applyAllowlist — CONTENT-KEYED matching (bead forge-mlk).
//
// THE PROBLEM THIS REPLACES. `ALLOWLIST` used to be keyed on (file, line): a
// row named the sink's exact line, so an edit ANYWHERE ABOVE a row shifted
// every row below it and forced a hand remap — the "LINE-DRIFT REMAP" and
// "MERGE remap" prose blocks that used to accumulate at the top of this file
// (deleted in the migration that landed this scheme; git history has them)
// were purely that bookkeeping, not audit content. A merge between two
// branches that both moved the same file collided on every row in between.
// Measured in lane M7-C alone: 6+ line-drift/merge conflicts in one day.
//
// THE NEW KEY. `{file, anchor}`, where `anchor` is computed by the SAME
// scanner that finds the sink (check-raw-fs-guarded.mjs's `analyzeModule`,
// via check-raw-fs-guarded.interproc.mjs's `anchorFor`): the sink's ENCLOSING
// TOP-LEVEL FUNCTION NAME (or `<module>` outside any) plus the sink's own
// normalized PATH EXPRESSION. Precedent: `PROJECTS_ROOT_FOLD_ALLOWLIST` above
// already keys on content (`{file, folded, site}`) rather than a line, for
// the same reason; this extends the same idea to the def-use ledger, with
// the enclosing function name added specifically so that two textually
// identical sink calls in two DIFFERENT functions don't collide under one
// row — an ambiguous row is a NAMED ERROR here (`ambiguous`, below), never a
// silent double-suppress or a silently-widened budget (the fold-allowlist's
// own docstring discloses that it tolerates exactly this collision, bounded
// by `count`; the bead asked for this ledger to be stricter).
//
// A row still carries `line` (kept fresh by the migration, refreshed whenever
// a row is next touched) — it is DISPLAY-ONLY, printed in `stale`/console
// output so a human has a place to start looking; matching never reads it.
// ---------------------------------------------------------------------------

function keyOf(f) {
  return `${f.file}\u0000${f.anchor}`;
}

/**
 * Suppress findings that carry an EXPLICIT, content-keyed allowlist entry.
 * Returns { kept, suppressed, stale, mistargeted, ambiguous }:
 *  - kept        = findings that FAIL the build (no valid allowlist entry).
 *  - suppressed  = findings cleared by a valid, reasoned entry.
 *  - stale       = allowlist entries matching NO finding (the audited
 *                  statement moved or changed) — reported as a warning, never
 *                  a failure (fail-safe: a stale entry cannot hide a real
 *                  finding, it only lingers).
 *  - mistargeted = an entry whose anchor HAS a finding but of a DIFFERENT
 *                  sink than recorded — the finding is KEPT (fails closed),
 *                  because a drifted entry must not silently bless a
 *                  different sink.
 *  - ambiguous   = an entry whose anchor matches findings at MORE distinct
 *                  lines than its declared `count` (default 1) — the row
 *                  cannot tell which location(s) it audited, so every
 *                  matching finding is KEPT (fails closed) until the anchor
 *                  is disambiguated (e.g. content drifted identically in two
 *                  functions of the same name — rename one, or add a
 *                  distinguishing detail upstream) OR the recurrence is
 *                  genuinely the SAME audited fact re-read at N call sites
 *                  (one binding, read twice in different branches of the
 *                  same function — e.g. `manifestPath` in
 *                  applyReviewVerdict), in which case the row states
 *                  `count: N` explicitly (precedent:
 *                  PROJECTS_ROOT_FOLD_ALLOWLIST's own `count`, above) — an
 *                  occurrence beyond the declared count is still ambiguous,
 *                  never silently absorbed.
 * An entry with an empty/whitespace reason is rejected (its finding is kept).
 */
export function applyAllowlist(findings, allowlist = ALLOWLIST) {
  const linesByKey = new Map();
  for (const f of findings) {
    const k = keyOf(f);
    if (!linesByKey.has(k)) linesByKey.set(k, new Set());
    linesByKey.get(k).add(f.line);
  }
  const byKey = new Map(allowlist.map((a) => [keyOf(a), a]));
  const kept = [];
  const suppressed = [];
  const mistargeted = [];
  const ambiguous = [];
  const usedKeys = new Set();
  for (const f of findings) {
    const k = keyOf(f);
    const a = byKey.get(k);
    if (!a) { kept.push(f); continue; }
    const distinctLines = linesByKey.get(k);
    const budget = a.count ?? 1;
    if (distinctLines.size > budget) {
      ambiguous.push({ entry: a, found: f });
      kept.push({ ...f, why: `${f.why} [ALLOWLIST ENTRY ${a.file} anchor="${a.anchor}" MATCHES ${distinctLines.size} DISTINCT LOCATIONS (lines ${[...distinctLines].sort((x, y) => x - y).join(',')}), OVER ITS DECLARED count (${budget}) — ambiguous, not suppressed; disambiguate the anchor or raise count after auditing the new occurrence too]` });
      continue;
    }
    if (!a.reason || !a.reason.trim()) {
      kept.push({ ...f, why: `${f.why} [ALLOWLIST ENTRY AT ${k} HAS NO REASON — rejected]` });
      continue;
    }
    const auditedSinks = a.sinks ?? (a.sink ? [a.sink] : null);
    if (auditedSinks && !auditedSinks.includes(f.sink)) {
      // The anchor matched but the recorded sink didn't — do NOT bless it.
      mistargeted.push({ entry: a, found: f });
      kept.push({ ...f, why: `${f.why} [allowlist entry at ${k} audited "${auditedSinks.join('|')}", found "${f.sink}" — mistargeted, not suppressed]` });
      continue;
    }
    usedKeys.add(k);
    suppressed.push({ ...f, reason: a.reason });
  }
  const stale = allowlist.filter((a) => !usedKeys.has(keyOf(a)));
  return { kept, suppressed, stale, mistargeted, ambiguous };
}
